export type WorkItem={id:string;screenRelevance:number;causalRelevance:number;uncertainty:number;motion:number;proofUrgency:number;cost:number;visible:boolean;};
export function workPriority(x:WorkItem){const numerator=.22*x.screenRelevance+.26*x.causalRelevance+.18*x.uncertainty+.14*x.motion+.20*x.proofUrgency;return numerator/Math.max(.01,x.cost)}
export function allocateWorkingSet(items:WorkItem[],budget:number){let used=0;const admitted:WorkItem[]=[];for(const x of [...items].sort((a,b)=>workPriority(b)-workPriority(a))){if(used+x.cost>budget)continue;used+=x.cost;admitted.push(x)}return{admitted,used,deferred:items.filter(x=>!admitted.includes(x))}}
